using System.Windows;
using System.Windows.Controls;
using SysAdminAssistant.Core;
using SysAdminAssistant.Infrastructure;
namespace SysAdminAssistant.Desktop;
public partial class MainWindow
{
    private sealed record LinuxVolumeRow(LinuxVolume Volume){public string Mount=>Volume.Mount;public string Source=>Volume.Source;public string Fs=>Volume.FileSystem;public string Kind=>Volume.DeviceKind;public string Size=>AgentIssueAdvice.Size(Volume.TotalBytes);public string Free=>AgentIssueAdvice.Size(Volume.AvailableBytes)+(Volume.TotalBytes>0?$" ({100d*Volume.AvailableBytes/Volume.TotalBytes:0.0}%)":"");public string Inodes=>Volume.Inodes is long n?Volume.FreeInodes+" / "+n:"нет данных";}
    private async Task LinuxVolumesWindow(int id,AgentView view,Window owner)
    {
        var p=Copy(view.Policy);p.Linux??=new();var rows=(view.Report==null?Array.Empty<LinuxVolume>():LinuxPolicy.Volumes(view.Report)).Select(v=>new LinuxVolumeRow(v)).ToArray();
        var window=new DialogWindow{Owner=owner,Title="Linux · тома, файловые системы и пороги",Width=1100,Height=640,WindowStartupLocation=WindowStartupLocation.CenterOwner};
        var table=Table(rows,("Точка монтирования","Mount",null),("Устройство / том","Source",null),("ФС","Fs",null),("Тип устройства","Kind",null),("Всего","Size",null),("Доступно","Free",null),("Inode свободно / всего","Inodes",null));var bar=new WrapPanel();bool busy=false;
        async Task Save(){AgentWire.Validate(p);p=await remote.CommandAsync<AgentPolicy>("agent-policy",new AgentPolicySave(id,p,p.Version),lifetime.Token);p.Linux??=new();}
        async Task Edit(){if(table.SelectedItem is not LinuxVolumeRow row)return;var d=LinuxPolicy.EffectiveDisk(row.Mount,p,row.Volume.TotalBytes);var f=new FormDialog(window,"Пороги · "+row.Mount,800).Note("Источник: "+row.Source+"; ФС "+row.Fs+". Пороги относятся к точке монтирования, а не к целому диску/LVM.").Toggle("enabled","Контролировать",d.Enabled).Text("percent","Свободно ≤ % · 0 выключает",d.FreePercent.ToString()).Text("mib","Свободно ≤ МиБ · 0 выключает",d.FreeMiB.ToString()).Text("inode","Inode свободно ≤ % · 0 выключает",d.InodeFreePercent.ToString()).Text("minimum","Свободных inode ≤ количество · 0 выключает",d.InodeMinimum.ToString()).Note("Условия срабатывают по ИЛИ. Разумный порог меньше объёма ФС. Автоматическая очистка не выполняется.");f.Validate=()=>{_=f.Number("percent",0,95);_=f.Number("mib",0,1000000000);_=f.Number("inode",0,95);_=f.Number("minimum",0,int.MaxValue);return null;};if(f.ShowDialog()!=true)return;p.Linux!.Disks.RemoveAll(x=>x.Mount==row.Mount);p.Linux.Disks.Add(new(row.Mount,f.Number("percent",0,95),f.Number("mib",0,1000000000),f.Number("inode",0,95),f.Number("minimum",0,int.MaxValue),f.Checked("enabled")));await Save();}
        void Button(string name,Func<Task> action){var b=UiButton(name);b.IsEnabled=AccessRules.Level(remote.CurrentUser,"devices")>=2;b.Click+=async(_,_)=>{if(busy)return;busy=true;bar.IsEnabled=false;try{await action();}catch(Exception e){AppMessageBox.Show(window,e.Message,"Пороги Linux",MessageBoxButton.OK,MessageBoxImage.Error);}finally{busy=false;bar.IsEnabled=true;}};bar.Children.Add(b);}
        Button("Пороги выбранной точки",Edit);Button("Вернуть стандартные пороги",async()=>{if(table.SelectedItem is LinuxVolumeRow row){p.Linux!.Disks.RemoveAll(d=>d.Mount==row.Mount);await Save();}});
        Button("Стандартные /boot и EFI",async()=>{var l=p.Linux!;var f=new FormDialog(window,"Стандартные пороги загрузочных ФС",780).Text("boot","/boot свободно ≤ %",l.BootFreePercent.ToString()).Text("bootmib","/boot свободно ≤ МиБ",l.BootFreeMiB.ToString()).Text("efi","/boot/efi свободно ≤ %",l.EfiFreePercent.ToString()).Text("efimib","/boot/efi свободно ≤ МиБ",l.EfiFreeMiB.ToString()).Text("inode","Стандартно inode свободно ≤ %",l.InodeFreePercent.ToString()).Text("swap","Swap занят ≥ % · 0 отключает",l.SwapUsedPercent.ToString()).Text("swapDelay","Задержка swap, минут",l.SwapDelayMinutes.ToString()).Note("На очень маленьком разделе стандартный абсолютный минимум ограничен 10% ёмкости. Индивидуальное правило точки имеет приоритет. Для остальных ФС используются общие пороги устройства.");f.Validate=()=>{_=f.Number("swap",0,100);_=f.Number("swapDelay",0,1440);_=f.Number("boot",0,95);_=f.Number("bootmib",0,1000000);_=f.Number("efi",0,95);_=f.Number("efimib",0,1000000);_=f.Number("inode",0,95);return null;};if(f.ShowDialog()!=true)return;l.SwapUsedPercent=f.Number("swap",0,100);l.SwapDelayMinutes=f.Number("swapDelay",0,1440);l.BootFreePercent=f.Number("boot",0,95);l.BootFreeMiB=f.Number("bootmib",0,1000000);l.EfiFreePercent=f.Number("efi",0,95);l.EfiFreeMiB=f.Number("efimib",0,1000000);l.InodeFreePercent=f.Number("inode",0,95);await Save();});
        table.SetValue(HasCustomDoubleClickProperty,true);table.MouseDoubleClick+=async(_,_)=>{if(!busy&&AccessRules.Level(remote.CurrentUser,"devices")>=2){busy=true;try{await Edit();}catch(Exception e){AppMessageBox.Show(window,e.Message);}finally{busy=false;}}};var layout=new DockPanel();DockPanel.SetDock(bar,Dock.Top);layout.Children.Add(bar);layout.Children.Add(table);window.Content=layout;window.ShowDialog();
    }
    private async Task AgentMetricHistoryWindow(int id,Window owner)
    {
        var window=new DialogWindow{Owner=owner,Title="История проверок агента",Width=1100,Height=680,WindowStartupLocation=WindowStartupLocation.CenterOwner};var items=new List<AgentMetricOccurrence>();long? before=null;bool busy=false;
        var table=Table(items,("Последнее","LastUtc","dd.MM.yyyy HH:mm:ss"),("Первое","FirstUtc","dd.MM.yyyy HH:mm:ss"),("Событие","Title",null),("Переход","Transition",null),("Наблюдений","Count",null),("Уровень","Severity",null));var details=new TextBox{IsReadOnly=true,TextWrapping=TextWrapping.Wrap,VerticalScrollBarVisibility=ScrollBarVisibility.Auto};table.SelectionChanged+=(_,_)=>{if(table.SelectedItem is AgentMetricOccurrence item)details.Text=item.Title+"\nСигнатура: "+item.Signature+"\n"+item.Details;};var more=UiButton("Загрузить ещё 200");
        async Task Load(){if(busy)return;busy=true;more.IsEnabled=false;try{var page=await remote.CommandAsync<AgentMetricHistoryPage>("agent-metric-history",new{DeviceId=id,Before=before},lifetime.Token);items.AddRange(page.Rows);table.ItemsSource=items.ToArray();before=page.Before;more.IsEnabled=before!=null;}finally{busy=false;}}
        more.Click+=async(_,_)=>{try{await Load();}catch(Exception e){AppMessageBox.Show(window,e.Message,"История");}};var root=new DockPanel();DockPanel.SetDock(more,Dock.Top);root.Children.Add(more);root.Children.Add(new ListInspector(table,details,"История показателей и systemd","Событий ещё нет","Новые срабатывания, повторения и восстановления сохраняются на сервере."));window.Content=root;await Load();window.ShowDialog();
    }    private async Task AgentJournalHistoryWindow(int id,AgentEventState state,Window owner)
    {
        var window=new DialogWindow{Owner=owner,Title="Архив журнала агента",Width=1100,Height=680,WindowStartupLocation=WindowStartupLocation.CenterOwner};var list=new List<AgentJournalEvent>();DateTime? before=null;string? beforeKey=null;bool busy=false;
        var table=Table(list,("Время события","TimeUtc","dd.MM.yyyy HH:mm:ss"),("Журнал","Channel",null),("Поставщик событий","Provider",null),("ID","Id",null),("Событие","Message",null));var details=new TextBox{IsReadOnly=true,TextWrapping=TextWrapping.Wrap,VerticalScrollBarVisibility=ScrollBarVisibility.Auto};table.SelectionChanged+=(_,_)=>{if(table.SelectedItem is AgentJournalEvent e)details.Text=AgentEventExplanation.DescribeEvent(state,e);};var more=UiButton("Загрузить ещё 200");
        async Task Load(){if(busy)return;busy=true;more.IsEnabled=false;try{var result=await remote.CommandAsync<AgentJournalHistoryPage>("agent-journal-history",new{DeviceId=id,BeforeUtc=before,BeforeKey=beforeKey},lifetime.Token);list.AddRange(result.Events);table.ItemsSource=list.ToArray();before=result.BeforeUtc;beforeKey=result.BeforeKey;more.IsEnabled=before!=null;}finally{busy=false;}}
        more.Click+=async(_,_)=>{try{await Load();}catch(Exception e){AppMessageBox.Show(window,e.Message,"Архив журнала");}};var root=new DockPanel();DockPanel.SetDock(more,Dock.Top);root.Children.Add(more);root.Children.Add(new ListInspector(table,details,"Архив событий","Записей ещё нет","Архив событий системного журнала Linux."));window.Content=root;await Load();window.ShowDialog();
    }

}
